style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("web.roblox.com") {
/* Background */
html,body{
  background:url("https://i.imgur.com/Zc8UI8Z.jpeg") no-repeat center center fixed!important;
  background-size:cover!important;
}

/* Remove Roblox’s built-in backgrounds */
#container,.container-main,.site-content,.rbx-body,.content,.page-content,.section,.container-header,.container-footer,
.rbx-left-col,.rbx-navbar,.rbx-header,.rbx-footer,.rbx-right-col,.sidebar,.nav-container{
  background:transparent!important;
}

/* Avatar connections – black circles */
.avatar-card .thumbnail-2d-container,
.avatar-card .thumbnail-2d,
.avatar-card .avatar-card-image,
.avatar-card .avatar-card-image-container,
.friend-list .avatar-card .thumbnail-2d,
.connections-list .avatar-card .thumbnail-2d{
  background-color:#000!important;
  border-radius:50%!important;
  overflow:hidden!important;
}

/* Game thumbnails stay rectangular */
.game-card .thumbnail-2d-container,
.game-card .thumbnail-2d,
.game-card img,
.thumbnail-2d-container.game-card,
.game-card-container .thumbnail-2d{
  border-radius:0!important;
  background:none!important;
}

/* Force all text black */
body,.text,.text-label,.avatar-name,.section-content,.item-name,.game-card-name,.profile-name,.section-title,
p,a,h1,h2,h3,h4,h5,h6,span{
  color:#000!important;
}

/* Sidebar icons (SVGs) to black */
.sidebar .icon,.icon-v2,.icon-xs,.icon-sm,.icon-md,.icon-lg svg path,
.sidebar .icon svg,.rbx-left-col svg path{
  fill:#000!important;
  color:#000!important;
}
}
